from Crypto.Cipher import DES

def decode_nibble(input_str, offset):
    mapping = "0123456789abcdef"
    output = ""
    nibble_length = len(str(offset))

    for i in range(0, len(input_str), nibble_length * 2):
        try:
            high_nibble = int(input_str[i : i + nibble_length]) - offset
            low_nibble = int(input_str[i + nibble_length : i + 2 * nibble_length]) - offset
            output += mapping[high_nibble] + mapping[low_nibble]
        except ValueError:
            continue

    return binascii.unhexlify(output)

def des_decrypt(input_bytes, key):
    iv = b"13371337"
    cipher = DES.new(key, DES.MODE_OFB, iv)
    msg = cipher.decrypt(input_bytes)
    return msg

def main():
    with open("DES2Bytes.enc", "r") as f:
        encoded_text = f.read().strip()

    # Decode the nibble-encoded ciphertext
    offset = 9133337
    decoded_ciphertext = decode_nibble(encoded_text, offset)

    # Attempt decryption using weak DES keys
    weak_keys = [
        binascii.unhexlify("0101010101010101"),
        binascii.unhexlify("FEFEFEFEFEFEFEFE"),
        binascii.unhexlify("E0E0E0E0F1F1F1F1"),
        binascii.unhexlify("1F1F1F1F0E0E0E0E"),
